const $=s=>document.querySelector(s), money=n=>n==null?'No disponible':new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n), num=(n,d=0)=>n==null?'Pendiente':new Intl.NumberFormat('es-CO',{maximumFractionDigits:d}).format(n), esc=s=>String(s??'No disponible').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let D,view='resumen',financial={start:'2026-07-01',end:'2026-09-18',route:'',bus:''},tracking={route:'',bus:'',state:'',time:'19:00'};
const names={resumen:'Resumen general',seguimiento:'Seguimiento',finanzas:'Finanzas',alertas:'Alertas y mantenimiento'};
const totals=rows=>{const complete=rows.length&&rows.every(x=>x.fuel!=null);const revenue=rows.length?rows.reduce((a,b)=>a+b.revenue,0):null,fuel=complete?rows.reduce((a,b)=>a+b.fuel,0):null,days=new Set(rows.map(x=>x.date)).size;return {revenue,fuel,partial:revenue!=null&&fuel!=null?revenue-fuel:null,passengers:rows.length?rows.reduce((a,b)=>a+b.passengers,0):null,gallons:complete?rows.reduce((a,b)=>a+b.gallons,0):null,days}};
const metric=(label,value,sub,featured=false)=>`<div class="metric ${featured?'featured':''}"><div class="label">${label}</div><div class="value">${value}</div><small>${sub}</small></div>`;
const stateClass=s=>({'En tránsito':'transit','Reserva':'reserve','En terminal':'terminal','Descanso conductor':'rest','Descanso del conductor':'rest'}[s]||'');
const status=s=>`<span class="status ${stateClass(s)}">${esc(s)}</span>`;
const date=s=>s?.slice(0,10).split('-').reverse().join('/')||'No disponible';
function latest(time='19:00'){const m=new Map;D.records.filter(r=>r.time<=time).forEach(r=>{if(!m.has(r.bus)||m.get(r.bus).time<r.time)m.set(r.bus,r)});return [...m.values()]}
function title(name,description,extra=''){return `<div class="title-row"><div><p class="eyebrow">KP TRANSPORTE</p><h1>${name}</h1><p>${description}</p></div>${extra}</div>`}
function sourceNotes(){return `<details><summary>Fuentes y criterios de cálculo</summary><p>Pasajeros transportados = subidas acumuladas, verificadas contra Trayectos y Pasajeros. Recaudo = Ingreso COP. Combustible consumido = Costo consumido COP de Combustible, no compras de Tanqueos. Ganancia parcial = ingresos − combustible consumido. Margen = ganancia parcial ÷ ingresos. Promedio diario = ganancia parcial ÷ días con registro, incluidos los días con reserva.</p><p>Julio y agosto completos. Septiembre disponible del 1 al 18, con el último día parcial hasta las 19:00. Los datos son ficticios y proceden de una simulación. Los estados de la flota corresponden al seguimiento del 18/09 y no cambian con el período financiero.</p><ul class="source-list">${D.sources.map(s=>`<li>${esc(s.file)}</li>`).join('')}</ul></details>`}
function overview(){const t=totals(D.daily.filter(r=>r.date>='2026-09-01'));const fleet=latest(),states={};fleet.forEach(r=>states[r.state]=(states[r.state]||0)+1);return title('Resumen general','Septiembre de 2026 · acumulado del 1 al 18',`<span class="badge amber">Período incompleto</span>`)+`<div class="metrics">${metric('Pasajeros transportados',num(t.passengers),'Subidas acumuladas del período')}${metric('Recaudo',money(t.revenue),'Ingresos registrados · COP')}${metric('Costos disponibles',money(t.fuel),'Combustible consumido únicamente')}${metric('Ganancia parcial',money(t.partial),'Faltan nómina, mantenimiento y otros gastos',true)}</div><div class="grid-two"><section class="panel fleet-overview"><div class="section-head"><div><h2>Estado de la flota</h2><p class="muted">18 sep 2026 · 19:00</p></div><span class="badge">Último registro</span></div><div class="fleet-big">12 <small>buses registrados</small></div><div class="state-counts">${Object.entries(states).map(([s,n])=>`<div><span>${s}</span><b>${n}</b></div>`).join('')}</div><a class="button" href="#seguimiento">Ver buses y rutas →</a><p class="muted" style="font-size:13px;margin:22px 0 0">Seguimiento histórico. Sin conexión en vivo.</p></section><section class="panel"><div class="section-head"><div><h2>Resultado del período</h2><p>Ingresos y ganancia parcial diaria</p></div><a href="#finanzas" class="text-button">Ver finanzas</a></div><div id="overview-chart"></div><div class="legend"><span>Ingresos</span><span class="profit">Ganancia parcial</span></div></section></div><section class="panel"><div class="section-head"><h2>Requiere atención</h2><a href="#alertas" class="text-button">Ver mantenimiento</a></div><div class="attention"><div><span class="badge green">0 alertas de aceite</span><p>Todos los buses conservan al menos 800 km hasta el próximo cambio.</p></div><div><span class="badge green">0 incidencias abiertas</span><p>Las 23 incidencias del histórico están registradas como resueltas.</p></div><div><span class="badge amber">Información parcial</span><p>El 18 de septiembre termina a las 19:00. Faltan costos para calcular la utilidad neta.</p></div></div></section>${sourceNotes()}`}
function render(){view=names[location.hash.slice(1)]?location.hash.slice(1):'resumen';$('#crumb').textContent=names[view];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);a.setAttribute('aria-current',a.dataset.view===view?'page':'false')});$('#main').innerHTML=({resumen:overview,seguimiento:monitor,finanzas:finance,alertas:alerts}[view])();if(view==='resumen')$('#overview-chart').innerHTML=lineChart(D.daily.filter(r=>r.date>='2026-09-01'));wire()}
function grouped(rows){const m=new Map;rows.forEach(r=>{if(!m.has(r.date))m.set(r.date,[]);m.get(r.date).push(r)});return [...m.entries()].sort().map(([date,rs])=>({date,...totals(rs)}))}
function lineChart(rows){const days=grouped(rows);if(!days.length)return '<div class="empty">Sin registros para los filtros seleccionados.</div>';const max=Math.max(...days.map(x=>x.revenue),1)*1.15,W=innerWidth<700?Math.max(240,innerWidth-74):680,H=240,left=58,right=18,top=15,bottom=38;const x=i=>left+(days.length===1?.5:i/(days.length-1))*(W-left-right),y=v=>H-bottom-v/max*(H-top-bottom);const path=key=>days.filter(d=>d[key]!=null).map((d,i)=>`${i?'L':'M'}${x(days.indexOf(d))},${y(d[key])}`).join(' ');return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución diaria de ingresos y ganancia parcial en millones de pesos. Valores exactos en el detalle diario.">${[0,.5,1].map(n=>`<line class="grid" x1="${left}" x2="${W-right}" y1="${y(max*n)}" y2="${y(max*n)}"/><text x="${left-9}" y="${y(max*n)+4}" text-anchor="end">${num(max*n/1e6,1)} M</text>`).join('')}<path d="${path('revenue')}" fill="none" stroke="var(--blue)" stroke-width="2.5"/><path d="${path('partial')}" fill="none" stroke="var(--green)" stroke-width="2.5"/>${days.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.revenue)}" r="3" fill="var(--blue)"><title>${date(d.date)} · Ingreso ${money(d.revenue)} · Ganancia parcial ${money(d.partial)}</title></circle>`).join('')}${[...new Set([0,Math.floor((days.length-1)/2),days.length-1])].map(i=>`<text x="${x(i)}" y="${H-9}" text-anchor="${i===0?'start':i===days.length-1?'end':'middle'}">${date(days[i].date).slice(0,5)}</text>`).join('')}</svg></div>`}
function select(label,name,options,value,scope){return `<label>${label}<select data-scope="${scope}" name="${name}" aria-label="${label}">${options.map(([val,text])=>`<option value="${esc(val)}" ${val===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function routeOptions(){return [['','Todas las rutas'],...D.routes.map(r=>[r['Código ruta'],`${r['Código ruta']} · ${r.Nombre}`])]}
function busOptions(route){return [['','Todos los buses'],...D.buses.filter(b=>!route||b['Ruta base']===route).map(b=>[b.Placa,b.Placa])]}
function filteredFleet(){return latest(tracking.time).filter(r=>(!tracking.route||r.route===tracking.route)&&(!tracking.bus||r.bus===tracking.bus)&&(!tracking.state||r.state===tracking.state))}
function busChip(b){return `<button class="bus-chip ${stateClass(b.state)}" data-bus="${b.bus}" aria-label="Ver ${b.bus}, ${esc(b.state)}"><strong>${b.bus}</strong><br>${esc(b.state)}${b.state==='En tránsito'?`<br>Hacia ${esc(b.next)}`:''}</button>`}
function monitor(){const fleet=filteredFleet();const all=latest(tracking.time);const states=['En parada','En tránsito','En terminal','Reserva',...new Set(D.records.filter(r=>r.state.toLowerCase().includes('descanso')).map(r=>r.state))];return title('Seguimiento','18 de septiembre de 2026 · registros cada 15 minutos',`<span class="badge">Información de las ${tracking.time}</span>`)+`<div class="note amber" style="margin-top:0">Último registro disponible: <strong>18/09/2026, 19:00</strong>. Sin conexión en vivo. No hay datos completados desde las 19:15; no se proyectan ubicaciones ni movimientos.</div><div class="filters">${select('Ruta','route',routeOptions(),tracking.route,'tracking')}${select('Bus','bus',busOptions(tracking.route),tracking.bus,'tracking')}${select('Estado','state',[['','Todos los estados'],...states.map(s=>[s,s])],tracking.state,'tracking')}${select('Hora del registro','time',[...new Set(D.records.map(r=>r.time))].sort().map(t=>[t,t==='19:00'?`${t} · último`:t]),tracking.time,'tracking')}<button class="button" data-reset="tracking">Restablecer</button></div><div class="fleet-strip"><span><strong>${fleet.length}</strong> buses visibles de ${all.length}</span>${states.map(s=>`<span>${s}: <strong>${fleet.filter(r=>r.state===s).length}</strong></span>`).join('')}<span><strong>${num(fleet.reduce((a,b)=>a+b.passengers,0))}</strong> pasajeros a bordo</span></div><p class="route-help">Esquema de paradas en orden de recorrido. Los buses en tránsito se asocian a la última parada conocida; su ubicación exacta no está disponible.</p>${fleet.length?'':'<div class="empty">No hay buses con esta combinación de filtros.</div>'}${D.routes.filter(r=>!tracking.route||r['Código ruta']===tracking.route).map(route=>{const code=route['Código ruta'],stops=D.stops.filter(s=>s.Ruta===code).sort((a,b)=>a.Orden-b.Orden),buses=fleet.filter(r=>r.route===code);return `<section class="panel route-panel" style="--route:${code==='KP01'?'#095981':'#2c8139'}"><div class="section-head"><div class="route-title"><span class="route-code">${code}</span><div><h2>${esc(route.Nombre)}</h2><p>Circular horario · ${buses.length} buses visibles · ${tracking.time}</p></div></div></div><div class="diagram">${stops.map((s,i)=>`<div class="stop"><button class="stop-button" data-stop="${s['Código parada']}" data-route="${code}" aria-label="Ver parada ${esc(s['Nombre de parada'])}, orden ${s.Orden}"><span class="node">${s.Orden}</span><span class="stop-name">${esc(s['Nombre de parada'])}</span><span class="stop-code">${s['Código parada']}${i===5?' · Regreso':''}</span></button>${i===5?'':buses.filter(b=>(b.current||b.last)===s['Nombre de parada']).map(busChip).join('')}</div>`).join('')}</div></section>`}).join('')}<section class="panel"><div class="section-head"><h2>Registros de buses</h2><span class="muted" style="font-size:14px">${tracking.time} · Bogotá</span></div><div class="table-scroll"><table><thead><tr><th>Bus / ruta</th><th>Estado</th><th>Parada actual o última</th><th>Próxima parada</th><th class="num">A bordo</th><th>Registro</th></tr></thead><tbody>${fleet.map(r=>`<tr><td><button class="text-button" data-bus="${r.bus}">${r.bus}</button><br><small>${r.route}</small></td><td>${status(r.state)}</td><td>${esc(r.current||r.last)}${!r.current?'<br><small class="muted">Última conocida</small>':''}</td><td>${esc(r.next||'No registrada')}</td><td class="num">${num(r.passengers)}</td><td>${date(r.date)}<br>${r.time}</td></tr>`).join('')}</tbody></table></div></section>`}
function financialRows(){return D.daily.filter(r=>r.date>=financial.start&&r.date<=financial.end&&(!financial.route||r.route===financial.route)&&(!financial.bus||r.bus===financial.bus))}
function monthRows(rows){return [...new Set(rows.map(r=>r.date.slice(0,7)))].sort().map(m=>{const rs=rows.filter(r=>r.date.startsWith(m)),dates=[...new Set(rs.map(r=>r.date))].sort();return {month:m,start:dates[0],end:dates.at(-1),...totals(rs)}})}
function finance(){const rows=financialRows(),t=totals(rows),days=grouped(rows),months=monthRows(rows);return title('Finanzas','Ingresos, consumo y ganancia parcial · COP')+`<div class="filters"><label>Desde<input type="date" name="start" data-scope="financial" value="${financial.start}" min="2026-07-01" max="2026-09-30"></label><label>Hasta<input type="date" name="end" data-scope="financial" value="${financial.end}" min="2026-07-01" max="2026-09-30"></label>${select('Ruta','route',routeOptions(),financial.route,'financial')}${select('Bus','bus',busOptions(financial.route),financial.bus,'financial')}<button class="button" data-reset="financial">Todo el período</button></div>${financial.start>financial.end?'<div class="note amber" role="alert">La fecha inicial debe ser anterior o igual a la fecha final.</div>':''}<p class="muted" style="font-size:14px">${date(financial.start)} a ${date(financial.end)} · ${t.days} días con registro${financial.end>='2026-09-18'?' · Septiembre incompleto, corte 18/09 a las 19:00':''}</p><div class="metrics finance-metrics">${metric('Ingresos',money(t.revenue),'Recaudo del período filtrado')}${metric('Combustible consumido',money(t.fuel),`${num(t.gallons,1)} galones estadounidenses`)}${metric('Ganancia parcial',money(t.partial),'Ingresos menos combustible consumido',true)}${metric('Margen parcial',t.revenue>0&&t.partial!=null?num(t.partial/t.revenue*100,1)+' %':'No disponible','Ganancia parcial / ingresos')}${metric('Promedio parcial diario',t.days&&t.partial!=null?money(t.partial/t.days):'No disponible',`${t.days} días con registro; incluye día parcial`)}${metric('Pasajeros transportados',num(t.passengers),'Subidas acumuladas, no ocupación')}</div><div class="note amber"><strong>No es utilidad neta.</strong> Faltan nómina, mantenimiento y otros gastos. Esos costos permanecen pendientes, no se consideran cero. Julio y agosto están completos; septiembre contiene 18 días y el 18/09 es parcial hasta las 19:00.</div><section class="panel"><div class="section-head"><div><h2>Evolución diaria</h2><p>Millones de COP · fechas y filtros seleccionados</p></div></div>${lineChart(rows)}<div class="legend"><span>Ingresos</span><span class="profit">Ganancia parcial</span></div></section><section class="panel" style="margin-top:24px"><div class="section-head"><div><h2>Comparación mensual</h2><p>Los meses reflejan el rango filtrado. Compare teniendo en cuenta los días disponibles.</p></div></div><div class="table-scroll"><table><thead><tr><th>Mes / cobertura</th><th class="num">Ingresos</th><th class="num">Combustible</th><th class="num">Ganancia parcial</th><th class="num">Promedio diario</th></tr></thead><tbody>${months.map(m=>{const complete=m.month!=='2026-09'&&m.days===31;return `<tr><td><strong>${({'2026-07':'Julio','2026-08':'Agosto','2026-09':'Septiembre'})[m.month]} 2026</strong><br><span class="badge ${complete?'green':'amber'}">${complete?'Completo':'Incompleto / parcial'} · ${m.days} días</span><br><small>${date(m.start)} – ${date(m.end)}</small></td><td class="num">${money(m.revenue)}</td><td class="num">${money(m.fuel)}</td><td class="num"><strong>${money(m.partial)}</strong></td><td class="num">${money(m.partial/m.days)}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Sin registros para los filtros seleccionados.</td></tr>'}</tbody></table></div></section><details class="panel"><summary>Consultar valores diarios (${days.length} días)</summary><div class="table-scroll"><table><thead><tr><th>Fecha</th><th class="num">Pasajeros</th><th class="num">Ingresos</th><th class="num">Combustible</th><th class="num">Ganancia parcial</th></tr></thead><tbody>${days.map(d=>`<tr><td>${date(d.date)}${d.date==='2026-09-18'?'<br><span class="badge amber">Hasta 19:00</span>':''}</td><td class="num">${num(d.passengers)}</td><td class="num">${money(d.revenue)}</td><td class="num">${money(d.fuel)}</td><td class="num">${money(d.partial)}</td></tr>`).join('')}</tbody></table></div></details>${sourceNotes()}`}
function alerts(){const rows=[...D.maintenance].sort((a,b)=>a['Km restantes']-b['Km restantes']),open=D.incidents.filter(r=>r.Estado!=='Resuelta'),due=rows.filter(r=>r['Km restantes']<800);return title('Alertas y mantenimiento','Último corte · 18 de septiembre de 2026, 19:00')+`<div class="metrics">${metric('Cambios de aceite por programar',num(due.length),'Regla: menos de 800 km restantes')}${metric('Incidencias abiertas',num(open.length),'Según el estado registrado')}${metric('Próximo bus al umbral',rows[0].Placa,`${num(rows[0]['Km restantes'],1)} km restantes; estado vigente`)}${metric('Incidencias históricas',num(D.incidents.length),'Julio a 18 de septiembre')}</div><div class="note ${due.length||open.length?'amber':''}">${due.length||open.length?'Revisar los vehículos con estado pendiente.':'No hay alertas activas de aceite ni incidencias abiertas al corte.'} <strong>Regla del archivo:</strong> programar cambio con menos de 800 km restantes; vencido con 0 km o menos. El mantenimiento preventivo se realiza en el bus de reserva, en terminal.</div><section class="panel"><div class="section-head"><div><h2>Próximos cambios de aceite</h2><p>Ordenados por kilómetros restantes · intervalos del catálogo de simulación</p></div></div><div class="table-scroll"><table><thead><tr><th>Vehículo / ruta</th><th>Estado y motivo</th><th class="num">Km restantes</th><th class="num">Odómetro actual</th><th class="num">Próximo cambio</th><th>Último cambio</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="text-button" data-bus="${r.Placa}" data-latest="true">${r.Placa}</button><br>${D.buses.find(b=>b.Placa===r.Placa)['Ruta base']}</td><td><span class="badge ${r['Km restantes']<800?'amber':'green'}">${esc(r['Estado aceite'])}</span><br><small class="muted">${r['Km restantes']<=0?'Límite de kilometraje alcanzado':r['Km restantes']<800?'Menos de 800 km restantes':'800 km o más restantes'}</small></td><td class="num"><strong>${num(r['Km restantes'],1)} km</strong><span class="oil-bar"><i style="width:${Math.max(0,Math.min(100,100*r['Km restantes']/r['Intervalo aceite km']))}%"></i></span></td><td class="num">${num(r['Odómetro final km'],1)}</td><td class="num">${num(r['Próximo aceite km'],1)}</td><td>${date(r['Último aceite fecha'])}</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="section-head"><div><h2>Incidencias registradas</h2><p>Histórico completo · las incidencias resueltas no se cuentan como alertas activas</p></div></div><div class="table-scroll"><table><thead><tr><th>Fecha / vehículo</th><th>Motivo</th><th>Atención</th><th>Estado</th><th class="num">Salidas afectadas</th></tr></thead><tbody>${[...D.incidents].sort((a,b)=>b.Fecha.localeCompare(a.Fecha)).map(r=>`<tr><td>${date(r.Fecha)}<br><button class="text-button" data-bus="${r.Placa}" data-latest="true">${r.Placa}</button></td><td>${esc(r.Incidencia)}</td><td>${esc(r.Resolución)}</td><td><span class="badge ${r.Estado==='Resuelta'?'green':'amber'}">${esc(r.Estado)}</span></td><td class="num">${num(r['Salidas afectadas'])}</td></tr>`).join('')}</tbody></table></div></section>${sourceNotes()}`}
function showDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#detail').open)$('#detail').showModal();bindDetailBuses()}
function showBus(bus,time=tracking.time){const r=latest(time).find(x=>x.bus===bus);if(!r)return;const route=D.routes.find(x=>x['Código ruta']===r.route);showDialog(r.bus,`${status(r.state)}<dl><dt>Placa</dt><dd>${r.bus}</dd><dt>Ruta</dt><dd>${r.route} · ${esc(route.Nombre)}</dd><dt>Conductor</dt><dd>${esc(r.driver||'Sin conductor asignado')}</dd><dt>Pasajeros a bordo</dt><dd>${num(r.passengers)}</dd><dt>${r.current?'Parada actual':'Última parada conocida'}</dt><dd>${esc(r.current||r.last)}</dd><dt>Próxima parada</dt><dd>${esc(r.next||'No registrada')}</dd><dt>Fecha y hora</dt><dd>${date(r.date)} · ${r.time}<br>Horario de Bogotá</dd></dl>${r.notes?`<p class="note">${esc(r.notes)}</p>`:''}${r.state==='En tránsito'?'<p class="note amber">El registro identifica el tramo entre dos paradas. La posición exacta no está disponible.</p>':''}<p class="muted" style="font-size:13px">Fuente: Seguimiento, 04-seguimiento-2026-09-18.xlsx.</p>`)}
function showStop(code,route){const s=D.stops.find(x=>x['Código parada']===code&&x.Ruta===route);const name=s['Nombre de parada'];const rs=filteredFleet().filter(b=>b.route===route&&(b.current===name||b.last===name||b.next===name));showDialog(name,`<p class="muted">${route} · ${code} · 18/09/2026, ${tracking.time}</p><p>Asociaciones según los registros y filtros seleccionados.</p>${rs.map(b=>`<div style="border-top:1px solid var(--line);padding:14px 0"><button class="text-button" data-bus="${b.bus}">${b.bus}</button> ${status(b.state)}<p style="font-size:14px;margin:8px 0">${b.current===name?'En esta parada':b.last===name?'Última parada conocida':'Próxima parada registrada'} · ${num(b.passengers)} a bordo · ${b.time}</p></div>`).join('')||'<div class="empty">Sin buses asociados a esta parada con los filtros seleccionados.</div>'}<p class="note">Una asociación como próxima parada no significa que el bus haya llegado.</p>`)}
function bindDetailBuses(){document.querySelectorAll('#dialog-body [data-bus]').forEach(b=>b.onclick=()=>showBus(b.dataset.bus))}
function reset(scope){if(scope==='tracking')tracking={route:'',bus:'',state:'',time:'19:00'};else financial={start:'2026-07-01',end:'2026-09-18',route:'',bus:''};render()}
function wire(){document.querySelectorAll('[data-scope]').forEach(el=>el.onchange=()=>{const state=el.dataset.scope==='tracking'?tracking:financial;state[el.name]=el.value;if(el.name==='route'&&state.bus&&!D.buses.some(b=>b.Placa===state.bus&&(!state.route||b['Ruta base']===state.route)))state.bus='';render()});document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>reset(b.dataset.reset));document.querySelectorAll('[data-bus]').forEach(b=>b.onclick=()=>showBus(b.dataset.bus,b.dataset.latest?'19:00':tracking.time));document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>showStop(b.dataset.stop,b.dataset.route))}
$('#close-detail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});window.addEventListener('hashchange',render);
try{const r=await fetch('data.json');if(!r.ok)throw new Error('No se pudieron cargar los datos');D=await r.json();render();if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'consultar_bus',description:'Abrir el detalle de un bus en el último registro disponible de las 19:00.',inputSchema:{type:'object',properties:{placa:{type:'string'}},required:['placa'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({placa})=>{if(!D.buses.some(b=>b.Placa===placa))throw new Error('Placa no registrada');showBus(placa,'19:00');return latest().find(r=>r.bus===placa)}})).catch(e=>console.warn("Herramienta de consulta no disponible",e))}}catch(e){$('#main').innerHTML=`<h1>No se pudieron cargar los registros</h1><p>Vuelve a cargar la página para intentar de nuevo.</p>`;console.error(e)}
